var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<UserStore>();
builder.Services.AddSingleton<SessionStore>();
var app = builder.Build();

// Credentials travel in a JSON body now (not the query string, where they'd
// end up in logs and shell history).
app.MapPost("/register", (Credentials creds, UserStore users) =>
{
    if (string.IsNullOrWhiteSpace(creds.Username) || string.IsNullOrWhiteSpace(creds.Password))
        return Results.BadRequest(new { error = "username and password are required" });
    if (creds.Password.Length < 8)
        return Results.BadRequest(new { error = "password must be at least 8 characters" });

    return users.Register(creds.Username, creds.Password)
        ? Results.Ok(new { registered = creds.Username })
        : Results.Conflict(new { error = "username taken" });
});

app.MapPost("/login", (Credentials creds, UserStore users, SessionStore sessions, HttpContext ctx) =>
{
    // One boring answer for bad username OR bad password — different answers
    // would let attackers test which usernames exist.
    if (creds.Username is null || creds.Password is null
        || !users.CheckPassword(creds.Username, creds.Password))
        return Results.Unauthorized();

    var token = sessions.Create(creds.Username);
    ctx.Response.Cookies.Append("session", token, new CookieOptions
    {
        HttpOnly = true,               // page JavaScript can't read it — XSS can't steal it
        SameSite = SameSiteMode.Lax,   // not sent on cross-site POSTs — blunts CSRF
        // In production, add Secure = true (HTTPS-only). Localhost demo skips it.
    });
    return Results.Ok(new { loggedIn = creds.Username });
});

app.MapGet("/me", (SessionStore sessions, HttpContext ctx) =>
{
    // The cookie holds a random token; only the server-side store can say
    // who it belongs to. A forged "session=admin" matches nothing.
    var user = sessions.UserFor(ctx.Request.Cookies["session"]);
    return user is null ? Results.Unauthorized() : Results.Ok(new { user });
});

app.MapPost("/logout", (SessionStore sessions, HttpContext ctx) =>
{
    // Revoke SERVER-SIDE first: even a copy of the cookie is now worthless.
    sessions.Revoke(ctx.Request.Cookies["session"]);
    ctx.Response.Cookies.Delete("session");
    return Results.Ok(new { loggedOut = true });
});

// Demo-only: what a breach would see NOW. Salted hashes — homework, not
// passwords. Compare the original's readable table.
app.MapGet("/debug/users", (UserStore users) => Results.Ok(users.Snapshot()));

app.Run("http://localhost:5023");

public record Credentials(string? Username, string? Password);

using System.Security.Cryptography;

// Server-side sessions: the cookie carries an OPAQUE random token — a claim
// check, not an identity. The token means nothing by itself; only this
// store's table (token -> username) gives it meaning, and only the server
// holds the table. Forging a login now means guessing a 256-bit random
// value; revoking one means deleting a dictionary entry. Compare the
// original, where the cookie WAS the identity and revocation was impossible.

public class SessionStore
{
    private readonly Dictionary<string, string> _userByToken = new();
    private readonly object _lock = new();

    public string Create(string username)
    {
        // 32 random bytes from the OS crypto source -> 64 hex chars.
        // (Random.Shared is fine for games, NEVER for tokens — it's predictable.)
        var token = Convert.ToHexString(RandomNumberGenerator.GetBytes(32));
        lock (_lock) _userByToken[token] = username;
        return token;
    }

    public string? UserFor(string? token)
    {
        if (token is null) return null;
        lock (_lock) return _userByToken.TryGetValue(token, out var user) ? user : null;
    }

    public bool Revoke(string? token)
    {
        if (token is null) return false;
        lock (_lock) return _userByToken.Remove(token);
    }
}

public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("PasswordHasher: the round trip");
        var hash = PasswordHasher.Hash("correct horse battery staple");
        Check.True(PasswordHasher.Verify("correct horse battery staple", hash),
            "the right password verifies against its hash");
        Check.True(!PasswordHasher.Verify("correct horse battery stapler", hash),
            "a wrong password (even one letter off) is rejected");
        Check.True(!hash.Contains("correct horse"),
            "the stored string does not contain the password");

        Console.WriteLine("PasswordHasher: salt means same password != same hash");
        var hashA = PasswordHasher.Hash("hunter2");
        var hashB = PasswordHasher.Hash("hunter2");
        Check.True(hashA != hashB, "two users with the same password get DIFFERENT hashes");
        Check.True(PasswordHasher.Verify("hunter2", hashA), "...and the first still verifies");
        Check.True(PasswordHasher.Verify("hunter2", hashB), "...and so does the second");

        Console.WriteLine("PasswordHasher: stored format");
        var parts = hashA.Split('$');
        Check.Equal(4, parts.Length, "stored string has 4 $-separated parts");
        Check.Equal("pbkdf2-sha256", parts[0], "part 0 names the algorithm");
        Check.Equal("100000", parts[1], "part 1 records the iteration count");

        Console.WriteLine("PasswordHasher: garbage in the store never verifies (and never throws)");
        Check.True(!PasswordHasher.Verify("anything", "hunter2"), "a plaintext-era entry verifies false");
        Check.True(!PasswordHasher.Verify("anything", ""), "empty stored string verifies false");
        Check.True(!PasswordHasher.Verify("anything", "pbkdf2-sha256$100000$!!!not-base64!!!$AAAA"),
            "corrupted base64 verifies false instead of throwing");

        Console.WriteLine("UserStore: register + check");
        var users = new UserStore();
        Check.True(users.Register("alice", "hunter2hunter2"), "first registration succeeds");
        Check.True(!users.Register("alice", "whatever-else"), "duplicate username is refused");
        Check.True(users.CheckPassword("alice", "hunter2hunter2"), "correct password checks out");
        Check.True(!users.CheckPassword("alice", "wrong-password"), "wrong password is rejected");
        Check.True(!users.CheckPassword("nobody", "hunter2hunter2"), "unknown user is rejected");
        Check.True(!users.Snapshot()["alice"].Contains("hunter2"),
            "the stored table contains no plaintext password");

        Console.WriteLine("SessionStore: opaque tokens, server-side truth");
        var sessions = new SessionStore();
        var token = sessions.Create("alice");
        Check.Equal(64, token.Length, "token is 64 hex chars (32 random bytes)");
        Check.True(!token.Contains("alice"), "token reveals nothing about the user");
        Check.Equal("alice", sessions.UserFor(token), "the store maps the token back to its user");
        Check.Equal(null, sessions.UserFor("session=admin-style-forgery"), "a made-up token maps to nobody");
        Check.Equal(null, sessions.UserFor(null), "no cookie, no user");

        var token2 = sessions.Create("alice");
        Check.True(token != token2, "every login gets a fresh token (two devices, two sessions)");

        Check.True(sessions.Revoke(token), "revoke removes the session");
        Check.Equal(null, sessions.UserFor(token), "a revoked token is dead, even if someone kept a copy");
        Check.True(!sessions.Revoke(token), "revoking twice reports false");
        Check.Equal("alice", sessions.UserFor(token2), "other sessions are untouched");

        return Check.Summary();
    }
}

// The user table: username -> stored hash string. The design goal, in one
// sentence: WE NEVER LEARN YOUR PASSWORD. It exists in memory for the
// milliseconds hashing takes, then only the salted hash remains. Even a
// full dump of this store hands an attacker homework, not credentials.

public class UserStore
{
    // One shared dummy hash, computed once at startup. See CheckPassword.
    private static readonly string DummyHash = PasswordHasher.Hash(Guid.NewGuid().ToString());

    private readonly Dictionary<string, string> _hashByUsername = new();
    private readonly object _lock = new();

    public bool Register(string username, string password)
    {
        var hash = PasswordHasher.Hash(password);   // slow on purpose — do it outside the lock
        lock (_lock)
        {
            if (_hashByUsername.ContainsKey(username)) return false;
            _hashByUsername[username] = hash;
            return true;
        }
    }

    public bool CheckPassword(string username, string password)
    {
        string? stored;
        lock (_lock) _hashByUsername.TryGetValue(username, out stored);

        // Unknown user? Verify against a dummy hash ANYWAY, so "no such user"
        // takes the same time as "wrong password". Answering instantly for
        // unknown names would let attackers discover which usernames exist
        // by timing responses (js#66's enumeration lesson).
        return PasswordHasher.Verify(password, stored ?? DummyHash) && stored is not null;
    }

    // Demo-only, so you can SEE what a breach would see now (compare the
    // original's /debug/users). A real app wouldn't expose even this.
    public IReadOnlyDictionary<string, string> Snapshot()
    {
        lock (_lock) return new Dictionary<string, string>(_hashByUsername);
    }
}
